using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UIElements;
using Jondo.UI.Generated;
using Jondo.UI.Models;

namespace Jondo.UI.Controllers
{
    public class ServerSelectionController
    {
        private readonly GeneratedServerSelectionBinding _binding;
        private List<ServerInfo> _servers;
        private int _selectedCardIdx = -1;
        private int _selectedServerId = -1;
        private int _carouselOffset = 0;
        private bool _isCarouselMode = true;

        public event Action<int> OnServerSelected;
        public event Action<int> OnServerPlay;

        public GeneratedServerSelectionBinding Binding => _binding;
        public int SelectedServerId => _selectedServerId;
        public int SelectedCardIndex => _selectedCardIdx;
        public bool IsCarouselMode => _isCarouselMode;

        public ServerSelectionController(VisualElement root)
        {
            _binding = new GeneratedServerSelectionBinding();
            _binding.Bind(root);
            SetupEventListeners();
        }

        private void SetupEventListeners()
        {
            // Mode toggle: Carousel vs List
            if (_binding.tg_carousel != null)
            {
                _binding.tg_carousel.RegisterCallback<ClickEvent>(evt => SetDisplayMode(true));
            }
            if (_binding.tg_list != null)
            {
                _binding.tg_list.RegisterCallback<ClickEvent>(evt => SetDisplayMode(false));
            }

            // Carousel navigation
            if (_binding.btn_moveLeft != null)
            {
                _binding.btn_moveLeft.RegisterCallback<ClickEvent>(evt =>
                {
                    if (_carouselOffset > 0)
                    {
                        _carouselOffset--;
                        RefreshCarousel();
                    }
                });
            }
            if (_binding.btn_moveRight != null)
            {
                _binding.btn_moveRight.RegisterCallback<ClickEvent>(evt =>
                {
                    if (_servers != null && _carouselOffset + 7 < _servers.Count)
                    {
                        _carouselOffset++;
                        RefreshCarousel();
                    }
                });
            }

            // Play button
            if (_binding.btn_play != null)
            {
                _binding.btn_play.RegisterCallback<ClickEvent>(evt =>
                {
                    if (_selectedServerId > 0)
                    {
                        OnServerPlay?.Invoke(_selectedServerId);
                    }
                });
            }
        }

        public void SetDisplayMode(bool isCarousel)
        {
            _isCarouselMode = isCarousel;
            if (_binding.ctr_carouselMode != null)
                _binding.ctr_carouselMode.style.display = isCarousel ? DisplayStyle.Flex : DisplayStyle.None;
            if (_binding.ctr_listMode != null)
                _binding.ctr_listMode.style.display = isCarousel ? DisplayStyle.None : DisplayStyle.Flex;

            if (_binding.tg_carousel != null)
            {
                var tc = _binding.tg_carousel.Q("toggle_container") ?? _binding.tg_carousel;
                tc.style.backgroundColor = isCarousel ? new Color(0.71f, 0.70f, 0.90f, 0.50f) : new Color(0.71f, 0.70f, 0.90f, 0.25f);
            }
            if (_binding.tg_list != null)
            {
                var tl = _binding.tg_list.Q("toggle_container") ?? _binding.tg_list;
                tl.style.backgroundColor = !isCarousel ? new Color(0.71f, 0.70f, 0.90f, 0.50f) : new Color(0.71f, 0.70f, 0.90f, 0.25f);
            }
        }

        public void InitServers(List<ServerInfo> servers)
        {
            _servers = servers;
            if (_servers == null || _servers.Count == 0)
            {
                if (_binding.lbl_noServer != null)
                {
                    _binding.lbl_noServer.style.display = DisplayStyle.Flex;
                    _binding.lbl_noServer.text = "Ningún servidor disponible";
                }
                if (_binding.ctr_carouselMode != null) _binding.ctr_carouselMode.style.display = DisplayStyle.None;
                return;
            }

            if (_binding.lbl_noServer != null)
            {
                _binding.lbl_noServer.style.display = DisplayStyle.None;
            }

            // Default selection: center or first with characters
            if (_selectedCardIdx < 0)
            {
                _selectedCardIdx = (_servers.Count > 1) ? 1 : 0;
            }
            if (_selectedCardIdx >= 0 && _selectedCardIdx < _servers.Count)
            {
                _selectedServerId = _servers[_selectedCardIdx].id;
            }

            RefreshCarousel();
        }

        public void SelectServer(int cardIdx, int serverId)
        {
            _selectedCardIdx = cardIdx;
            _selectedServerId = serverId;
            OnServerSelected?.Invoke(serverId);
            RefreshCarousel();
        }

        private void RefreshCarousel()
        {
            if (_servers == null || _binding.Root == null) return;

            for (int i = 0; i < 7; i++)
            {
                var card = _binding.Root.Q($"serverCard_{i}");
                if (card == null) continue;

                int srvIdx = _carouselOffset + i;
                if (srvIdx >= _servers.Count)
                {
                    card.style.display = DisplayStyle.None;
                    continue;
                }

                card.style.display = DisplayStyle.Flex;
                var srv = _servers[srvIdx];

                // Responsive pitch & elevation formula from live dump
                card.style.width = 340;
                card.style.height = 630;
                card.style.marginLeft = 17.5f;
                card.style.marginRight = 17.5f;

                bool isSelected = (i == _selectedCardIdx);
                int dist = Math.Abs(i - _selectedCardIdx);

                if (isSelected)
                {
                    card.style.marginTop = -50;
                    card.style.borderLeftColor = new Color(0.95f, 0.77f, 0.25f, 1f);
                    card.style.borderRightColor = new Color(0.95f, 0.77f, 0.25f, 1f);
                    card.style.borderTopColor = new Color(0.95f, 0.77f, 0.25f, 1f);
                    card.style.borderBottomColor = new Color(0.95f, 0.77f, 0.25f, 1f);
                    card.style.borderLeftWidth = 3;
                    card.style.borderRightWidth = 3;
                    card.style.borderTopWidth = 3;
                    card.style.borderBottomWidth = 3;
                }
                else
                {
                    card.style.marginTop = (dist == 1) ? 0 : 50;
                    card.style.borderLeftWidth = 1;
                    card.style.borderRightWidth = 1;
                    card.style.borderTopWidth = 1;
                    card.style.borderBottomWidth = 1;
                    card.style.borderLeftColor = new Color(0.3f, 0.35f, 0.4f, 0.5f);
                    card.style.borderRightColor = new Color(0.3f, 0.35f, 0.4f, 0.5f);
                    card.style.borderTopColor = new Color(0.3f, 0.35f, 0.4f, 0.5f);
                    card.style.borderBottomColor = new Color(0.3f, 0.35f, 0.4f, 0.5f);
                }

                int localIdx = i;
                int localId = srv.id;
                var clickArea = card.Q("ctr_cardClickableArea") ?? card;
                clickArea.RegisterCallback<ClickEvent>(evt => SelectServer(localIdx, localId));
            }
        }
    }
}
